-- db/seed/funders/axis_bank.sql
-- GENERATED from seed/data/funders/axis-bank-csr-fy2023-24-to-fy2025-26.json. Edit the JSON.
-- Loads Axis Bank Limited and Axis Bank Foundation: themes, programmes and phases, stated
-- priorities, CSR obligation per year, sector spend, footprints (districts for the North
-- East, states elsewhere), partners and programme metrics. Every row points to its source
-- report, registered in documents. Idempotent. Run after db/seed/reference_data.sql.

BEGIN;

CREATE OR REPLACE FUNCTION pg_temp.funder(p_slug text) RETURNS bigint LANGUAGE sql STABLE AS
$$ SELECT id FROM funders WHERE slug = p_slug $$;

CREATE OR REPLACE FUNCTION pg_temp.state_id(p_state text) RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE v bigint;
BEGIN
  SELECT id INTO v FROM locations
  WHERE kind = 'state' AND (lower(name) = lower(p_state)
                            OR EXISTS (SELECT 1 FROM unnest(aliases) a WHERE lower(a) = lower(p_state)))
  ORDER BY id LIMIT 1;
  IF v IS NULL THEN
    INSERT INTO locations (kind, name, parent_id)
    VALUES ('state', p_state, (SELECT id FROM locations WHERE kind = 'country' AND name = 'India' AND parent_id IS NULL))
    RETURNING id INTO v;
  END IF;
  RETURN v;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.district_id(p_state text, p_district text, p_aliases text[] DEFAULT '{}') RETURNS bigint
LANGUAGE plpgsql AS $$
DECLARE v bigint; v_state bigint := pg_temp.state_id(p_state); v_names text[];
BEGIN
  SELECT array_agg(lower(x)) INTO v_names FROM unnest(p_aliases || p_district) x;
  SELECT id INTO v FROM locations l
  WHERE l.kind = 'district' AND l.parent_id = v_state
    AND (lower(l.name) = ANY (v_names) OR EXISTS (SELECT 1 FROM unnest(l.aliases) a WHERE lower(a) = ANY (v_names)))
  ORDER BY l.id LIMIT 1;
  IF v IS NULL THEN
    INSERT INTO locations (kind, name, parent_id, aliases) VALUES ('district', p_district, v_state, p_aliases)
    RETURNING id INTO v;
  END IF;
  RETURN v;
END $$;

-- States: add the spellings the reports use as aliases
UPDATE locations SET aliases = (SELECT array_agg(DISTINCT x) FROM unnest(aliases || '{Jammu & Kashmir}'::text[]) x) WHERE id = pg_temp.state_id('Jammu and Kashmir');
UPDATE locations SET aliases = (SELECT array_agg(DISTINCT x) FROM unnest(aliases || '{Andaman & Nicobar}'::text[]) x) WHERE id = pg_temp.state_id('Andaman and Nicobar Islands');
UPDATE locations SET aliases = (SELECT array_agg(DISTINCT x) FROM unnest(aliases || '{Dadra & Nagar Haveli and Daman & Diu}'::text[]) x) WHERE id = pg_temp.state_id('Dadra and Nagar Haveli and Daman and Diu');

