UPDATE funder_footprints SET notes = coalesce(notes || '; ', '') || 'Tamil Nadu is on the state list, but the district table covers 5 states and has no Tamil Nadu district.'
WHERE funder_id = pg_temp.funder('axis-bank') AND fiscal_year = 'FY2023-24' AND program_id = (SELECT id FROM programs WHERE funder_id = pg_temp.funder('axis-bank') AND name = 'Environmental Sustainability')
  AND (notes IS NULL OR position('Tamil Nadu is on the state list, but the district table covers 5 states and has no Tamil Nadu district.' IN notes) = 0);
UPDATE funder_footprints SET notes = coalesce(notes || '; ', '') || 'The state list has 4 states; the district table also lists Uttar Pradesh (Baghpat, Lucknow) and West Bengal (Kolkata, North 24 Paraganas).'
WHERE funder_id = pg_temp.funder('axis-bank') AND fiscal_year = 'FY2024-25' AND program_id = (SELECT id FROM programs WHERE funder_id = pg_temp.funder('axis-bank') AND name = 'Humanitarian & Relief')
  AND (notes IS NULL OR position('The state list has 4 states; the district table also lists Uttar Pradesh (Baghpat, Lucknow) and West Bengal (Kolkata, North 24 Paraganas).' IN notes) = 0);

