-- Link partners that are already in the registry, by exact name
UPDATE funder_partners fp SET org_id = o.id FROM orgs o WHERE fp.org_id IS NULL AND lower(o.name) = lower(fp.partner_name);

-- One spelling per partner, so renewals across years can be counted
UPDATE funder_partners SET partner_canonical = CASE partner_name
  WHEN 'Peepul Trust' THEN 'Peepul'
  WHEN 'National Integrity and Educational Development Organisation India' THEN 'NIEDO'
  WHEN 'Centre for Wildlife Studies (CWS)' THEN 'Centre for Wildlife Studies'
  WHEN 'Center for Wildlife Studies' THEN 'Centre for Wildlife Studies'
  WHEN 'Balipara Tract & Frontier Foundation' THEN 'Balipara Foundation'
  WHEN 'Foundation for Ecological Security (FES)' THEN 'Foundation for Ecological Security'
  WHEN 'Nature Environment & Wildlife Society (NEWS)' THEN 'Nature Environment and Wildlife Society'
  WHEN 'Nature Environment and Wildlife Society (NEWS)' THEN 'Nature Environment and Wildlife Society'
  WHEN 'Sewa Mandir' THEN 'Seva Mandir'
  WHEN 'Greenyatra' THEN 'Green Yatra'
  WHEN 'Institute of Rural Management Anand (IRMA)' THEN 'Institute of Rural Management Anand'
  WHEN 'Institute of Rural Management, Anand' THEN 'Institute of Rural Management Anand'
  WHEN 'Indian Institute of Science (IISc)' THEN 'Indian Institute of Science'
  WHEN '17000 ft Foundation' THEN '17000 ft Foundation'
  WHEN 'Step up for India' THEN 'Step Up For India'
  WHEN 'Muheem Ek Sarthak Prayas Welfare Society' THEN 'Muheem'
  WHEN 'LIFI' THEN 'Learning Initiatives for India'
  WHEN 'Mantra 4 Change' THEN 'Mantra Social Services'
  WHEN 'Inspire Institute of Sport (IIS)' THEN 'Inspire Institute of Sport'
  WHEN 'Foundation for Promotion of Sports & Games (FPSG)' THEN 'Foundation for Promotion of Sports and Games'
  WHEN 'National Cancer Grid (Tata Memorial Centre)' THEN 'National Cancer Grid'
  WHEN 'National Cancer Grid, Tata Memorial Center' THEN 'National Cancer Grid'
  WHEN 'Indian Cancer Society (ICS)' THEN 'Indian Cancer Society'
  ELSE partner_name END
WHERE funder_id = pg_temp.funder('axis-bank');

COMMIT;
